{
  "name": "AA Opto MDS 声光可调滤波器",
  "name_en": "AA Opto MDS Acousto-Optic Tunable Filter",
  "manufacturer": "AA Opto-Electronic",
  "description": "这是一台 AA Opto 的 MDS 系列声光可调滤波器/控制单元，用于按通道控制激光光路的透过、射频驱动功率和工作频率，从而实现特定波长或光束的快速选通与强度调节。该设备常用于荧光显微、激光扫描和多激光实验中的快速波长选择与光强调制。",
  "description_en": "This is an AA Opto MDS-series acousto-optic tunable filter and controller used to control laser transmission, RF drive power, and operating frequency on individual channels, enabling fast wavelength selection and intensity modulation. It is commonly used in fluorescence microscopy, laser scanning, and multi-laser laboratory setups for rapid optical switching and beam control.",
  "tag_hints": [
    "AOTF",
    "acousto-optic tunable filter",
    "laser modulation",
    "multi-channel optical switching",
    "RF power control",
    "wavelength selection",
    "fluorescence microscopy"
  ],
  "actions": [
    {
      "action_name": "auto-query",
      "description": "向设备发送原始串口命令并读取返回信息。",
      "description_en": "Send a raw serial command to the device and read back its response."
    },
    {
      "action_name": "auto-GetStatus",
      "description": "读取设备当前状态和初始属性。",
      "description_en": "Read the device's current status and initial properties."
    },
    {
      "action_name": "auto-Enable",
      "description": "启用指定通道的光学输出。",
      "description_en": "Enable the optical output of the specified channel."
    },
    {
      "action_name": "auto-Disable",
      "description": "禁用指定通道的光学输出。",
      "description_en": "Disable the optical output of the specified channel."
    },
    {
      "action_name": "auto-SetPower",
      "description": "设置指定通道的射频驱动功率。",
      "description_en": "Set the RF drive power for the specified channel."
    },
    {
      "action_name": "auto-GetPower",
      "description": "读取指定通道的射频驱动功率设置。",
      "description_en": "Read the RF drive power setting of the specified channel."
    },
    {
      "action_name": "auto-SetPowerAndEnable",
      "description": "设置指定通道的射频驱动功率并启用该通道。",
      "description_en": "Set the RF drive power for the specified channel and enable that channel."
    },
    {
      "action_name": "auto-SetFreq",
      "description": "设置指定通道的工作频率。",
      "description_en": "Set the operating frequency of the specified channel."
    },
    {
      "action_name": "auto-GetFreq",
      "description": "读取指定通道的工作频率设置。",
      "description_en": "Read the operating frequency setting of the specified channel."
    },
    {
      "action_name": "auto-Close",
      "description": "关闭活动通道并断开设备连接。",
      "description_en": "Shut down active channels and disconnect from the device."
    }
  ]
}

